import type { Metadata } from "next";
import localFont from "next/font/local";
import "./globals.css";
import { Toaster } from "@/components/ui/Toaster";
import RootLayoutClient from "@/components/layout/RootLayoutClient";
import LiveMetricsWidget from "@/components/common/LiveMetricsWidget";
import IntlProviderWithFallback from "@/components/layout/IntlProviderWithFallback";
import { getLocale, getMessages, getTranslations } from "next-intl/server";
import { BRAND } from "@/constants/brand";

// Self-hosted so the Docker build never has to reach Google Fonts: Turbopack
// leaves every @font-face unresolved when fonts.googleapis.com is unreachable
// from the build container, which fails `next build`.
const inter = localFont({
  src: [{ path: "./fonts/InterVariable.woff2", weight: "100 900", style: "normal" }],
  display: "swap",
  variable: "--font-sans",
  fallback: ["system-ui", "Segoe UI", "sans-serif"],
});


export async function generateMetadata(): Promise<Metadata> {
  const locale = await getLocale();
  const t = await getTranslations({ locale, namespace: 'Metadata' });
  const tagline = t('tagline');
  const description = t('description');
  const keywords = t.raw('keywords') as string[];
  const title = `${BRAND.name} - ${tagline}`;

  return {
    metadataBase: new URL(BRAND.domain),
    title: {
      default: title,
      template: `%s | ${BRAND.name}`,
    },
    description,
    keywords,
    authors: [{ name: `${BRAND.name} Team` }],
    creator: BRAND.name,
    publisher: BRAND.name,
    alternates: {
      canonical: '/',
    },
    openGraph: {
      title,
      description,
      siteName: BRAND.name,
      url: BRAND.domain,
      type: 'website',
      locale: locale === 'en' ? 'en_US' : 'vi_VN',
      images: [
        {
          url: BRAND.assets.logo512,
          width: 512,
          height: 512,
          alt: title,
        },
      ],
    },
    twitter: {
      card: 'summary_large_image',
      title,
      description,
      images: [BRAND.assets.logo512],
    },
    icons: {
      icon: [
        { url: BRAND.assets.favicon, sizes: 'any' },
        { url: '/icon.png', type: 'image/png', sizes: '512x512' },
        { url: BRAND.assets.logo512, type: 'image/png', sizes: '512x512' },
        { url: BRAND.assets.logoIcon, type: 'image/svg+xml' },
      ],
      shortcut: [
        { url: BRAND.assets.favicon },
        { url: '/icon.png', type: 'image/png' },
      ],
      apple: [
        { url: BRAND.assets.appleTouchIcon, sizes: '180x180', type: 'image/png' },
      ],
    },
  };
}

export default async function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  const locale = await getLocale();
  const [messages, metadataT] = await Promise.all([
    getMessages(),
    getTranslations({ locale, namespace: 'Metadata' }),
  ]);
  const tagline = metadataT('tagline');
  const description = metadataT('description');

  const structuredSchemas = [
    {
      '@context': 'https://schema.org',
      '@type': 'SportsOrganization',
      name: BRAND.name,
      alternateName: [
        'SportO - Chơi cùng nhau',
        'SportO Giải Đấu',
        'SportO Thể Thao',
        'SportO Asia',
      ],
      slogan: tagline,
      url: BRAND.domain,
      logo: {
        '@type': 'ImageObject',
        url: `${BRAND.domain}/sporto_512.png`,
        width: '512',
        height: '512',
      },
      image: `${BRAND.domain}/sporto_1024.png`,
      description: `${BRAND.name} - ${tagline}. ${description}`,
      sameAs: [
        'https://play.google.com/store/apps/details?id=com.sporto.app',
      ],
    },
    {
      '@context': 'https://schema.org',
      '@type': 'WebSite',
      name: BRAND.name,
      alternateName: `${BRAND.name} - ${tagline}`,
      url: BRAND.domain,
      potentialAction: {
        '@type': 'SearchAction',
        target: {
          '@type': 'EntryPoint',
          urlTemplate: `${BRAND.domain}/tournaments?q={search_term_string}`,
        },
        'query-input': 'required name=search_term_string',
      },
    },
  ];

  return (
    <html lang={locale} className={`h-full antialiased ${inter.variable}`} suppressHydrationWarning>
      <head>
        <link rel="icon" type="image/x-icon" href="/favicon.ico" sizes="any" />
        <link rel="shortcut icon" href="/favicon.ico" />
        <link rel="icon" href="/icon.png" type="image/png" sizes="512x512" />
        <link rel="icon" href="/sporto_512.png" type="image/png" sizes="512x512" />
        <link rel="apple-touch-icon" href="/apple-touch-icon.png" sizes="180x180" />
        <link rel="manifest" href="/manifest.webmanifest" />
        {structuredSchemas.map((schema, index) => (
          <script
            key={index}
            type="application/ld+json"
            dangerouslySetInnerHTML={{ __html: JSON.stringify(schema) }}
          />
        ))}
      </head>
      <body className={`min-h-full flex flex-col text-slate-900 font-sans ${inter.className}`}>
        <IntlProviderWithFallback locale={locale} messages={messages}>
          <RootLayoutClient>{children}</RootLayoutClient>
          <Toaster />
          <LiveMetricsWidget />
        </IntlProviderWithFallback>
      </body>
    </html>
  );
}

