@import "tailwindcss";
@import "../styles/transitions.css";
@config "../../tailwind.config.ts";

@theme {
  --color-primary: var(--color-primary);
  --color-primary-hover: var(--color-primary-hover);
  --color-primary-light: var(--color-primary-light);
  --color-primary-foreground: var(--color-primary-foreground);

  --color-blue-50: var(--color-primary-light);
  --color-blue-100: var(--color-accent);
  --color-blue-500: var(--color-primary);
  --color-blue-600: var(--color-primary);
  --color-blue-650: var(--color-primary-hover);
  --color-blue-700: var(--color-primary-hover);
}

:root {
    --color-background: #ffffff; /* pure white background */
    --color-foreground: #0f172a; /* slate-900 */

    --color-primary: rgb(29, 142, 248); /* Web Primary rgb(29, 142, 248) / #1d8ef8 */
    --color-primary-hover: #002461; /* SportO Primary Hover Navy #002461 */
    --color-primary-foreground: #ffffff;
    --color-primary-light: #b2cffd; /* primary tint */

    --color-secondary: #3ab5f6; /* SportO Cyan Accent */

    --color-card: #ffffff;
    --color-card-foreground: #0f172a;

    --color-muted: #475569; /* slate-600 */
    --color-muted-foreground: #64748b; /* slate-500 */

    --color-accent: #d6e2f7; /* blue-100 */
    --color-accent-foreground: #002e7c; /* logo navy */

    --color-border: #e2e8f0; /* slate-200 */
    --color-input: #e2e8f0; /* slate-200 */
